<script lang="ts">
  export interface Device { name: string; kind: string; confidence: 'confirmed'|'likely'|'unknown'; evidence: string; availability: string; firstSeen: string; lastSeen: string; }
  interface Props { devices?: Device[]; }
  let { devices = [] }: Props = $props(); let query = $state(''); let tab = $state('all');
  const visible = $derived(devices.filter((d) => (tab === 'all' || d.confidence === tab) && d.name.toLowerCase().includes(query.toLowerCase())));
</script>
<section class="devices-view" aria-labelledby="devices-heading"><div class="view-heading"><div><p class="kicker">DEVICES / IDENTITY</p><h1 id="devices-heading">Know what is home.</h1><p class="muted">Identity is earned from evidence, never guessed from a name alone.</p></div></div><label class="search"><span>Search devices</span><input bind:value={query} placeholder="e.g. living room TV" /></label><div class="tabs" role="tablist">{#each [['all','All'],['confirmed','Confirmed'],['likely','Needs confirm']] as item}<button class:active={tab === item[0]} on:click={() => tab = item[0]} role="tab" aria-selected={tab === item[0]}>{item[1]}</button>{/each}</div>{#if visible.length === 0}<div class="empty-state device-empty"><span class="empty-icon">⌁</span><div><strong>No devices to show</strong><p class="muted">Pair NeonHearth to begin building a private device list.</p></div></div>{:else}<div class="device-table">{#each visible as device}<article class="device-card"><div class="device-name"><span class="device-symbol">◌</span><div><strong>{device.name}</strong><span>{device.kind}</span></div></div><span class="confidence {device.confidence}">{device.confidence === 'confirmed' ? '✓ Confirmed' : device.confidence === 'likely' ? '△ Needs confirm' : '○ Unknown'}</span><p><b>Evidence</b>{device.evidence}</p><p><b>Availability</b>{device.availability}</p><p><b>Seen</b>{device.firstSeen} → {device.lastSeen}</p></article>{/each}</div>{/if}</section>
